export const schema = {"$schema":"http://json-schema.org/draft-07/schema#","version":"1.2.0","generatedAt":"2026-05-16","package":"@usevyre/react","packageVersion":"1.1.0","validFor":["@usevyre/react@1.1.0+","@usevyre/vue@1.1.0+"],"changelog":{"1.2.0":{"date":"2026-05-16","breaking":false,"summary":"Added Item layout primitive, DateRangePicker (dual-month range picker with presets, built on Calendar) and Kanban (controlled drag-and-drop board); Calendar gained additive defaultMonth prop; DatePicker split into its own documented component/entry"},"1.1.0":{"date":"2026-05-15","breaking":false,"summary":"Added 6 components: ButtonGroup, TagsInput, Combobox, DataGrid, Tag, TagGroup"},"1.0.0":{"date":"2026-05-13","breaking":true,"summary":"Stable v1.0 release — VyreCode renamed to Code in Vue, BreadcrumbLink + BreadcrumbSeparator added to React, Toast setup updated"},"0.2.0":{"date":"2026-05-08","breaking":false,"summary":"Added structured schema, anti-patterns JSON, per-tool format generation"},"0.1.1":{"date":"2026-05-06","breaking":false,"summary":"Initial AI context with full-context.md, cursor/claude/windsurf/copilot formats"}},"components":{"Accordion":{"description":"Vertically stacked collapsible sections. Compose with AccordionItem, AccordionTrigger, AccordionContent.","import":"import { Accordion, AccordionItem, AccordionTrigger, AccordionContent } from \"@usevyre/react\"","subcomponents":["AccordionItem","AccordionTrigger","AccordionContent"],"props":{},"antiPatterns":[{"pattern":"Accordion without AccordionItem","reason":"Accordion requires AccordionItem as direct child","fix":"Always compose: Accordion > AccordionItem > AccordionTrigger + AccordionContent"}],"examples":[{"description":"Basic accordion","code":"<Accordion>\n  <AccordionItem value=\"item-1\">\n    <AccordionTrigger>Section Title</AccordionTrigger>\n    <AccordionContent>Content goes here.</AccordionContent>\n  </AccordionItem>\n</Accordion>"}]},"Alert":{"description":"Inline feedback message for info, success, warning, or danger states.","import":"import { Alert } from \"@usevyre/react\"","props":{"variant":{"type":"enum","values":["info","success","warning","danger"],"default":"info","description":"Visual severity style"},"title":{"type":"string","description":"Bold heading text inside the alert"},"onClose":{"type":"function","description":"If provided, renders a close (×) button"}},"antiPatterns":[{"pattern":"variant=\"error\"","reason":"No 'error' variant exists","fix":"Use variant=\"danger\""},{"pattern":"variant=\"primary\"","reason":"Alert uses severity variants, not brand variants","fix":"Use variant=\"info\" | \"success\" | \"warning\" | \"danger\""}],"examples":[{"description":"Warning with close button","code":"<Alert variant=\"warning\" title=\"Heads up\" onClose={() => setOpen(false)}>\n  This action cannot be undone.\n</Alert>"},{"description":"Success state","code":"<Alert variant=\"success\" title=\"Saved!\">Your changes have been saved.</Alert>"}]},"Avatar":{"description":"User profile image with fallback initials or icon.","import":"import { Avatar } from \"@usevyre/react\"","props":{"src":{"type":"string","description":"Image URL. Falls back to `fallback` if not provided or fails to load."},"alt":{"type":"string","default":"\"\"","description":"Alt text for the image"},"fallback":{"type":"string","description":"Text or initials shown when image is absent"},"size":{"type":"enum","values":["sm","md","lg","xl"],"default":"md","description":"Avatar diameter"},"status":{"type":"enum","values":["online","offline","busy","away"],"description":"Optional status indicator dot"}},"antiPatterns":[{"pattern":"size=\"xs\"","reason":"Minimum size is 'sm'","fix":"Use size=\"sm\""},{"pattern":"size=\"2xl\"","reason":"Maximum size is 'xl'","fix":"Use size=\"xl\""}],"examples":[{"description":"Avatar with image and online status","code":"<Avatar src=\"/user.png\" alt=\"Jane Doe\" size=\"lg\" status=\"online\" />"},{"description":"Fallback initials","code":"<Avatar fallback=\"JD\" size=\"md\" />"}]},"Badge":{"description":"Small label for status, category, or count. Use dot prop for live status indicator.","import":"import { Badge } from \"@usevyre/react\"","props":{"variant":{"type":"enum","values":["default","accent","teal","success","warning","danger"],"default":"default","description":"Color style of the badge"},"dot":{"type":"boolean","default":false,"description":"Shows a pulsing status indicator dot"}},"antiPatterns":[{"pattern":"variant=\"primary\"","reason":"Badge has no 'primary' variant","fix":"Use variant=\"accent\" for brand color"},{"pattern":"variant=\"error\"","reason":"No 'error' variant exists","fix":"Use variant=\"danger\""},{"pattern":"variant=\"info\"","reason":"No 'info' variant on Badge (use Alert for info messages)","fix":"Use variant=\"teal\" for info-like styling"}],"examples":[{"description":"Live status with dot","code":"<Badge variant=\"success\" dot>Online</Badge>"},{"description":"Warning badge","code":"<Badge variant=\"warning\">Beta</Badge>"},{"description":"Danger badge","code":"<Badge variant=\"danger\">Error</Badge>"}]},"Breadcrumb":{"description":"Navigation trail showing current page location in hierarchy.","import":"import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbSeparator } from \"@usevyre/react\"","subcomponents":["BreadcrumbItem","BreadcrumbLink","BreadcrumbSeparator"],"props":{},"antiPatterns":[{"pattern":"Using plain <a> tags inside Breadcrumb","reason":"Use BreadcrumbLink for correct styling and accessibility","fix":"Use BreadcrumbItem > BreadcrumbLink for each crumb"}],"examples":[{"description":"Basic breadcrumb","code":"<Breadcrumb>\n  <BreadcrumbItem><BreadcrumbLink href=\"/\">Home</BreadcrumbLink></BreadcrumbItem>\n  <BreadcrumbSeparator />\n  <BreadcrumbItem><BreadcrumbLink href=\"/docs\">Docs</BreadcrumbLink></BreadcrumbItem>\n  <BreadcrumbSeparator />\n  <BreadcrumbItem aria-current=\"page\">Button</BreadcrumbItem>\n</Breadcrumb>"}]},"Button":{"description":"Triggers actions and navigation. The most commonly used interactive element.","import":"import { Button } from \"@usevyre/react\"","props":{"variant":{"type":"enum","values":["primary","secondary","ghost","accent","teal","danger"],"default":"secondary","description":"Visual style. primary=high contrast CTA, secondary=bordered, ghost=minimal, accent=amber brand, teal=secondary accent, danger=destructive"},"size":{"type":"enum","values":["sm","md","lg","icon"],"default":"md","description":"Size scale. Use 'icon' for square icon-only buttons"},"loading":{"type":"boolean","default":false,"description":"Shows spinner and disables interaction"},"disabled":{"type":"boolean","default":false,"description":"Disables the button"},"as":{"type":"React.ElementType","default":"\"button\"","description":"Render as different element (e.g. 'a' for link buttons)"},"leftIcon":{"type":"ReactNode","description":"Icon rendered before the label"},"rightIcon":{"type":"ReactNode","description":"Icon rendered after the label"}},"accessibility":{"notes":["Always add aria-label when using size='icon' (no visible text)"]},"antiPatterns":[{"pattern":"variant=\"blue\"","reason":"No 'blue' variant exists","fix":"Use variant=\"accent\" for brand amber, or variant=\"teal\" for teal"},{"pattern":"size=\"xl\"","reason":"Maximum size is 'lg'","fix":"Use size=\"lg\""},{"pattern":"color=\"...\"","reason":"No color prop exists on Button","fix":"Use variant prop instead"},{"pattern":"icon={...}","reason":"No 'icon' prop for inserting icons","fix":"Use leftIcon={...} or rightIcon={...}"},{"pattern":"size=\"icon\" without aria-label","reason":"Icon-only buttons have no visible text — screen readers need aria-label","fix":"Add aria-label describing the action"}],"examples":[{"description":"Primary CTA","code":"<Button variant=\"primary\">Get Started</Button>"},{"description":"Large accent button","code":"<Button variant=\"accent\" size=\"lg\">Launch App</Button>"},{"description":"Loading state","code":"<Button variant=\"danger\" loading>Deleting...</Button>"},{"description":"Link button","code":"<Button as=\"a\" href=\"/docs\" variant=\"secondary\">Read Docs</Button>"},{"description":"Icon-only button","code":"<Button variant=\"ghost\" size=\"icon\" aria-label=\"Close\">\n  <X size={16} />\n</Button>"}]},"Calendar":{"description":"Inline date-grid widget (always visible, no input). mode: single | range | multiple, optional time picker. For an input + popover use DatePicker; for start/end ranges with presets use DateRangePicker.","import":"import { Calendar } from \"@usevyre/react\"","props":{"value":{"type":"Date | null","description":"Currently selected date (controlled)"},"onChange":{"type":"function","description":"Callback when a date is selected"},"disabled":{"type":"boolean","default":false},"defaultMonth":{"type":"Date","description":"Month to display initially when value is empty (uncontrolled view). Used by DateRangePicker for the second month."}},"antiPatterns":[{"pattern":"Calendar for an input field that opens a popover","reason":"Calendar renders an always-visible grid, not a trigger","fix":"Use <DatePicker /> (single date) or <DateRangePicker /> (range)"},{"pattern":"value as tuple for mode=\"single\"","reason":"value type must match mode: Date for single, [Date,Date] for range, Date[] for multiple","fix":"Pass value matching mode; use mode=\"range\" for [start,end]"}],"examples":[{"description":"Controlled date picker","code":"const [date, setDate] = useState(null);\n<Calendar value={date} onChange={setDate} />"}]},"DatePicker":{"description":"Input trigger that opens a Calendar in a popover. Same modes as Calendar (single | range | multiple) plus a placeholder. Use this for a compact date field; use Calendar for an always-visible grid, or DateRangePicker for start/end ranges with presets.","import":"import { DatePicker } from \"@usevyre/react\"","props":{"value":{"type":"Date | [Date, Date] | Date[] | null","description":"Selected value (controlled). Type must match mode."},"onChange":{"type":"function","description":"Callback when the selection changes; argument shape matches mode"},"mode":{"type":"enum","values":["single","range","multiple"],"default":"single","description":"Selection mode"},"placeholder":{"type":"string","default":"Pick a date","description":"Trigger text when nothing is selected"},"showTime":{"type":"boolean","default":false,"description":"Adds an HH:MM time picker (single mode)"},"minDate":{"type":"Date","description":"Earliest selectable date"},"maxDate":{"type":"Date","description":"Latest selectable date"},"disabled":{"type":"function","description":"(date: Date) => boolean — disable specific dates"},"weekStartsOn":{"type":"enum","values":[0,1],"default":1,"description":"0 = Sunday, 1 = Monday"},"inputClassName":{"type":"string","description":"Class on the trigger button"}},"antiPatterns":[{"pattern":"DatePicker mode=\"range\" for { from, to } object","reason":"DatePicker range mode emits a [Date, Date] tuple, not a { from, to } object","fix":"Use <DateRangePicker /> for the { from, to } object API + presets + dual month"},{"pattern":"DatePicker without value/onChange","reason":"DatePicker is controlled — it has no internal selected state","fix":"Provide value and onChange (e.g. from useState)"}],"examples":[{"description":"Single date field","code":"const [date, setDate] = useState(null);\n<DatePicker value={date} onChange={setDate} placeholder=\"Pick a date\" />"},{"description":"Date + time","code":"<DatePicker value={date} onChange={setDate} showTime />"}]},"Card":{"description":"Content container with optional header, body, and footer sections.","import":"import { Card, CardHeader, CardBody, CardFooter } from \"@usevyre/react\"","subcomponents":["CardHeader","CardBody","CardFooter"],"props":{"variant":{"type":"enum","values":["default","elevated","outlined","ghost","accent"],"default":"default","description":"Visual style of the card"},"hoverable":{"type":"boolean","default":false,"description":"Adds hover lift effect"},"clickable":{"type":"boolean","default":false,"description":"Adds cursor pointer and active press feedback"}},"antiPatterns":[{"pattern":"variant=\"primary\"","reason":"Card has no 'primary' variant","fix":"Use variant=\"elevated\" | \"outlined\" | \"ghost\" | \"accent\""}],"examples":[{"description":"Elevated card with sections","code":"<Card variant=\"elevated\">\n  <CardHeader><Badge variant=\"teal\">New</Badge></CardHeader>\n  <CardBody>\n    <h3>Card Title</h3>\n    <p>Description text.</p>\n  </CardBody>\n  <CardFooter>\n    <Button variant=\"ghost\" size=\"sm\">Learn more</Button>\n  </CardFooter>\n</Card>"}]},"Checkbox":{"description":"Binary toggle for boolean form values.","import":"import { Checkbox } from \"@usevyre/react\"","props":{"size":{"type":"enum","values":["sm","md"],"default":"md"},"checked":{"type":"boolean","description":"Controlled checked state"},"onChange":{"type":"function","description":"Callback on change"},"disabled":{"type":"boolean","default":false},"indeterminate":{"type":"boolean","default":false,"description":"Shows dash icon for partial selection state"}},"antiPatterns":[{"pattern":"size=\"lg\"","reason":"Maximum size is 'md'","fix":"Use size=\"md\""}],"examples":[{"description":"Labeled checkbox","code":"<label style={{ display: 'flex', alignItems: 'center', gap: 'var(--vyre-spacing-2)' }}>\n  <Checkbox checked={agreed} onChange={e => setAgreed(e.target.checked)} />\n  I agree to the terms\n</label>"}]},"RadioGroup":{"description":"Controlled single-choice group. RadioGroup owns the selected value; render it data-driven via the options array OR with composable <Radio> children for custom content. role=radiogroup with proper labelling. For multi-select use Checkbox; for a compact dropdown use Select.","import":"import { RadioGroup, Radio } from \"@usevyre/react\"","subcomponents":["Radio"],"props":{"value":{"type":"string","description":"Selected value (controlled). Vue: v-model."},"defaultValue":{"type":"string","description":"Initial value (uncontrolled, React only)"},"onChange":{"type":"function","description":"(value: string) => void. Vue: update:modelValue / v-model."},"name":{"type":"string","description":"Radio input name; auto-generated if omitted"},"disabled":{"type":"boolean","default":false,"description":"Disable the whole group"},"size":{"type":"enum","values":["sm","md"],"default":"md","description":"Control size"},"orientation":{"type":"enum","values":["vertical","horizontal"],"default":"vertical","description":"Layout direction"},"options":{"type":"{ value: string; label?: string; description?: string; disabled?: boolean }[]","description":"Data-driven options. Omit to pass <Radio> children instead."}},"antiPatterns":[{"pattern":"<Radio> used outside a <RadioGroup>","reason":"Radio reads selection + name from RadioGroup context; it throws without a provider","fix":"Always wrap <Radio> in <RadioGroup>"},{"pattern":"RadioGroup without value/onChange (React) or v-model (Vue)","reason":"RadioGroup is controlled; selection won't update","fix":"Bind value + onChange (React) or v-model (Vue); or defaultValue for uncontrolled in React"},{"pattern":"Using Checkbox for mutually-exclusive choices","reason":"Radio expresses single-choice semantics + keyboard model","fix":"Use RadioGroup + Radio (or options) for one-of-many"}],"examples":[{"description":"Data-driven","code":"<RadioGroup\n  value={plan}\n  onChange={setPlan}\n  options={[\n    { value: \"free\", label: \"Free\", description: \"For hobby projects\" },\n    { value: \"pro\",  label: \"Pro\",  description: \"For teams\" },\n  ]}\n/>"},{"description":"Composable children","code":"<RadioGroup value={plan} onChange={setPlan} orientation=\"horizontal\">\n  <Radio value=\"free\" label=\"Free\" />\n  <Radio value=\"pro\"  label=\"Pro\" />\n</RadioGroup>"}]},"RichTextEditor":{"description":"Controlled WYSIWYG editor. value is an HTML string; you own it in state and set it in onChange (React) / v-model (Vue). Native contentEditable + execCommand — zero dependencies. Toolbar: bold, italic, underline, strike, h1-h3, ordered/unordered lists, quote, code block, link, clear formatting.","import":"import { RichTextEditor } from \"@usevyre/react\"","props":{"value":{"type":"string","description":"HTML content (controlled). React: value + onChange. Vue: v-model."},"onChange":{"type":"function","description":"(html: string) => void. Vue: update:modelValue / v-model."},"placeholder":{"type":"string","default":"Write something…","description":"Shown when the editor is empty"},"disabled":{"type":"boolean","default":false,"description":"Not editable, dimmed; toolbar disabled"},"readOnly":{"type":"boolean","default":false,"description":"Not editable; toolbar hidden entirely"},"toolbar":{"type":"RichTextTool[]","description":"Which buttons to show. Default = all. Tools: \"bold\"|\"italic\"|\"underline\"|\"strike\"|\"h1\"|\"h2\"|\"h3\"|\"ul\"|\"ol\"|\"quote\"|\"code\"|\"link\"|\"clear\""},"minHeight":{"type":"string","default":"10rem","description":"CSS min-height of the editable area"}},"antiPatterns":[{"pattern":"RichTextEditor without value/onChange (React) or v-model (Vue)","reason":"It is fully controlled; edits won't persist","fix":"Keep the HTML string in state and update it in onChange / v-model"},{"pattern":"Rendering value as text or with dangerouslySetInnerHTML elsewhere without sanitising","reason":"value is raw HTML the user typed","fix":"Sanitise (e.g. DOMPurify) before re-rendering untrusted RTE output"},{"pattern":"toolbar=\"bold\" (string)","reason":"toolbar is an array of tool ids","fix":"Pass an array, e.g. toolbar={[\"bold\",\"italic\",\"link\"]}"}],"examples":[{"description":"Controlled editor","code":"const [html, setHtml] = useState(\"<p>Hello <strong>world</strong></p>\");\n<RichTextEditor value={html} onChange={setHtml} placeholder=\"Write…\" />"},{"description":"Minimal toolbar","code":"<RichTextEditor\n  value={html}\n  onChange={setHtml}\n  toolbar={[\"bold\", \"italic\", \"link\"]}\n/>"}]},"Command":{"description":"Command palette / search dialog. Use for search-first navigation or quick actions.","import":"import { Command, CommandInput, CommandList, CommandEmpty, CommandGroup, CommandItem, CommandDialog } from \"@usevyre/react\"","subcomponents":["CommandInput","CommandList","CommandEmpty","CommandGroup","CommandItem","CommandDialog"],"props":{},"antiPatterns":[{"pattern":"Using Input type=\"search\" for search UI","reason":"Command component is the correct pattern for search-first UI","fix":"Use Command + CommandInput + CommandList + CommandItem"}],"examples":[{"description":"Basic command palette","code":"<Command>\n  <CommandInput placeholder=\"Search...\" />\n  <CommandList>\n    <CommandEmpty>No results found.</CommandEmpty>\n    <CommandGroup heading=\"Suggestions\">\n      <CommandItem onSelect={() => handleSelect('dashboard')}>Dashboard</CommandItem>\n      <CommandItem onSelect={() => handleSelect('settings')}>Settings</CommandItem>\n    </CommandGroup>\n  </CommandList>\n</Command>"}]},"DropdownMenu":{"description":"Contextual menu triggered by a button. Supports items, separators, checkbox items, radio groups, and sub-menus.","import":"import { DropdownMenu, DropdownItem, DropdownSeparator, DropdownCheckboxItem, DropdownRadioGroup, DropdownRadioItem, DropdownSub } from \"@usevyre/react\"","subcomponents":["DropdownItem","DropdownSeparator","DropdownCheckboxItem","DropdownRadioGroup","DropdownRadioItem","DropdownSub"],"props":{"trigger":{"type":"ReactElement","description":"Element that opens the dropdown when clicked"}},"itemProps":{"variant":{"type":"enum","values":["default","danger"],"default":"default","description":"Use 'danger' for destructive actions"}},"antiPatterns":[{"pattern":"DropdownItem variant=\"primary\"","reason":"DropdownItem only has 'default' and 'danger' variants","fix":"Use variant=\"danger\" for destructive items only"}],"examples":[{"description":"Dropdown with danger item","code":"<DropdownMenu trigger={<Button variant=\"secondary\">Options</Button>}>\n  <DropdownItem onSelect={() => handleEdit()}>Edit</DropdownItem>\n  <DropdownItem onSelect={() => handleDuplicate()}>Duplicate</DropdownItem>\n  <DropdownSeparator />\n  <DropdownItem variant=\"danger\" onSelect={() => handleDelete()}>Delete</DropdownItem>\n</DropdownMenu>"}]},"Field":{"description":"Form field wrapper. Two ways to use it (both supported): (1) props-based — pass label/hint/state/required for the common case; (2) composable — use the parts FieldLabel, FieldDescription, FieldError, FieldGroup, FieldSet for richer layouts (multiple controls, custom error placement). The props-based API is unchanged and still works.","import":"import { Field, Input, Textarea } from \"@usevyre/react\"","props":{"label":{"type":"string","description":"Visible field label"},"hint":{"type":"string","description":"Helper or error text below the input"},"state":{"type":"enum","values":["idle","error","success","warning"],"default":"idle","description":"Validation state — affects border color and hint text color"},"required":{"type":"boolean","default":false,"description":"Shows required indicator"}},"antiPatterns":[{"pattern":"Applying state prop directly to Input","reason":"state belongs on Field, not on the Input itself","fix":"Wrap Input in <Field state=\"error\"> to apply validation styling"},{"pattern":"Mixing props label/hint AND FieldLabel/FieldError for the same field","reason":"Duplicates the label / message","fix":"Pick one: either props-based (label/hint/state) OR composable parts"}],"examples":[{"description":"Error state field","code":"<Field label=\"Email\" state=\"error\" hint=\"Invalid email format\">\n  <Input type=\"email\" placeholder=\"you@example.com\" />\n</Field>"},{"description":"Search field with left icon","code":"<Field label=\"Search\">\n  <Input leftElement={<SearchIcon />} placeholder=\"Search...\" />\n</Field>"},{"description":"Composable field with explicit parts","code":"<Field>\n  <FieldLabel required htmlFor=\"email\">Email</FieldLabel>\n  <Input id=\"email\" type=\"email\" />\n  <FieldDescription>We\\u2019ll never share it.</FieldDescription>\n  <FieldError>{errors.email}</FieldError>\n</Field>\n\n// Two controls side by side\n<FieldGroup orientation=\"horizontal\">\n  <Field label=\"First name\"><Input /></Field>\n  <Field label=\"Last name\"><Input /></Field>\n</FieldGroup>"}],"subcomponents":["FieldLabel","FieldDescription","FieldError","FieldGroup","FieldSet"]},"Input":{"description":"Text input field. Wrap in Field for labels and validation. Use leftElement/rightElement for icons.","import":"import { Input } from \"@usevyre/react\"","props":{"modelValue":{"type":"string | number","description":"Vue only: enables v-model (two-way binding). React: use native value + onChange. Native input attrs (type, placeholder, disabled…) work in both."},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Height and text size scale. Note: 'icon' size is NOT valid for Input"},"leftElement":{"type":"ReactNode","description":"Icon or element rendered inside the input on the left"},"rightElement":{"type":"ReactNode","description":"Icon or element rendered inside the input on the right"}},"antiPatterns":[{"pattern":"size=\"icon\"","reason":"'icon' size is only valid for Button, not Input","fix":"Use size=\"sm\" | \"md\" | \"lg\""},{"pattern":"type=\"search\" for search UI","reason":"Use Command component for search-first interfaces","fix":"Import Command from @usevyre/react for search palettes"},{"pattern":"Vue: binding Input/Textarea value without v-model","reason":"Vue Input & Textarea support v-model (modelValue); manual :value alone won't update","fix":"Use v-model on <Input>/<Textarea> in Vue; in React use value + onChange"}],"examples":[{"description":"Password input with icon","code":"<Input type=\"password\" rightElement={<EyeIcon />} placeholder=\"Password\" />"}]},"Label":{"description":"Accessible form label. Associate with input via htmlFor.","import":"import { Label } from \"@usevyre/react\"","props":{"htmlFor":{"type":"string","description":"ID of the associated input element"},"required":{"type":"boolean","default":false}},"examples":[{"description":"Label with input","code":"<Label htmlFor=\"email\">Email address</Label>\n<Input id=\"email\" type=\"email\" />"}]},"Modal":{"description":"Dialog overlay for confirmations, forms, or focused content.","import":"import { Modal, ModalHeader, ModalBody, ModalFooter } from \"@usevyre/react\"","subcomponents":["ModalHeader","ModalBody","ModalFooter"],"props":{"open":{"type":"boolean","description":"Controls visibility (controlled mode)"},"onClose":{"type":"function","description":"Called when modal is dismissed"},"size":{"type":"enum","values":["sm","md","lg","full"],"default":"md","description":"Width of the modal dialog"},"title":{"type":"string","description":"Accessible dialog title (also shown as heading)"}},"antiPatterns":[{"pattern":"size=\"xl\"","reason":"Maximum size is 'full'","fix":"Use size=\"lg\" or size=\"full\""}],"examples":[{"description":"Confirmation modal","code":"<Modal open={isOpen} onClose={() => setIsOpen(false)} title=\"Confirm Delete\" size=\"sm\">\n  <ModalBody>Are you sure you want to delete this item?</ModalBody>\n  <ModalFooter>\n    <Button variant=\"ghost\" onClick={() => setIsOpen(false)}>Cancel</Button>\n    <Button variant=\"danger\" onClick={handleDelete}>Delete</Button>\n  </ModalFooter>\n</Modal>"}]},"Pagination":{"description":"Page navigation for paginated lists or tables.","import":"import { Pagination } from \"@usevyre/react\"","props":{"page":{"type":"number","description":"Current page (1-indexed)"},"total":{"type":"number","description":"Total number of pages"},"onChange":{"type":"function","description":"Called with new page number when user navigates"}},"examples":[{"description":"Basic pagination","code":"<Pagination page={currentPage} total={totalPages} onChange={setCurrentPage} />"}]},"Popover":{"description":"Floating content panel anchored to a trigger element. For simple labels use Tooltip instead.","import":"import { Popover } from \"@usevyre/react\"","props":{"trigger":{"type":"ReactElement","description":"Element that opens the popover"},"placement":{"type":"enum","values":["top","top-start","top-end","bottom","bottom-start","bottom-end","left","left-start","left-end","right","right-start","right-end"],"default":"bottom","description":"Preferred placement relative to trigger"},"open":{"type":"boolean","description":"Controlled open state"},"onOpenChange":{"type":"function","description":"Callback when open state changes"},"closeOnOutside":{"type":"boolean","default":true,"description":"Close when clicking outside"}},"antiPatterns":[{"pattern":"placement=\"top-center\"","reason":"No 'top-center' — center alignment is the default when no suffix is given","fix":"Use placement=\"top\" for centered placement"}],"examples":[{"description":"Popover with custom content","code":"<Popover trigger={<Button variant=\"secondary\">More info</Button>} placement=\"bottom-start\">\n  <div style={{ padding: 'var(--vyre-spacing-4)' }}>\n    <p>Detailed information here.</p>\n  </div>\n</Popover>"}]},"Progress":{"description":"Visual progress indicator for tasks, uploads, or completion status.","import":"import { Progress } from \"@usevyre/react\"","props":{"value":{"type":"number","description":"Progress value (0–100)"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Height of the progress bar"},"variant":{"type":"enum","values":["default","accent","teal","success","danger"],"default":"default","description":"Color variant"}},"antiPatterns":[{"pattern":"value > 100","reason":"Value is clamped to 0–100","fix":"Normalize your value to 0–100 range before passing"}],"examples":[{"description":"Upload progress","code":"<Progress value={uploadPercent} variant=\"accent\" size=\"sm\" />"}]},"Select":{"description":"Dropdown for selecting one option from a list.","import":"import { Select } from \"@usevyre/react\"","props":{"options":{"type":"SelectOption[]","description":"Array of { value: string, label: string } objects"},"value":{"type":"string","description":"Controlled selected value"},"onChange":{"type":"function","description":"Called with new value string on selection"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md"},"placeholder":{"type":"string","description":"Placeholder text when no value is selected"},"disabled":{"type":"boolean","default":false}},"antiPatterns":[{"pattern":"Passing strings directly as children","reason":"Select uses options prop, not children","fix":"Pass options={[{ value: 'a', label: 'Option A' }]}"}],"examples":[{"description":"Controlled select","code":"<Select\n  options={[{ value: 'react', label: 'React' }, { value: 'vue', label: 'Vue' }]}\n  value={framework}\n  onChange={setFramework}\n  placeholder=\"Choose framework\"\n/>"}]},"Separator":{"description":"Horizontal or vertical divider line.","import":"import { Separator } from \"@usevyre/react\"","props":{"orientation":{"type":"enum","values":["horizontal","vertical"],"default":"horizontal"}},"examples":[{"description":"Horizontal separator","code":"<Separator />"},{"description":"Vertical separator","code":"<Separator orientation=\"vertical\" />"}]},"Sheet":{"description":"Side panel (drawer) that slides in from the edge. For forms, detail views, or settings.","import":"import { Sheet, SheetHeader, SheetBody, SheetFooter } from \"@usevyre/react\"","subcomponents":["SheetHeader","SheetBody","SheetFooter"],"props":{"open":{"type":"boolean","description":"Controls visibility"},"onClose":{"type":"function","description":"Called when sheet is dismissed"},"size":{"type":"enum","values":["sm","md","lg","full"],"default":"md","description":"Width of the sheet panel"},"side":{"type":"enum","values":["left","right"],"default":"right","description":"Which edge the sheet slides from"},"title":{"type":"string","description":"Accessible panel title"}},"examples":[{"description":"Settings sheet from the right","code":"<Sheet open={isOpen} onClose={() => setIsOpen(false)} title=\"Settings\" side=\"right\">\n  <SheetBody>Settings content here.</SheetBody>\n  <SheetFooter>\n    <Button variant=\"accent\">Save</Button>\n  </SheetFooter>\n</Sheet>"}]},"Sidebar":{"description":"App navigation sidebar. Use AppLayout as the root layout wrapper.","import":"import { AppLayout, Sidebar, SidebarHeader, SidebarContent, SidebarSection, SidebarItem, SidebarFooter } from \"@usevyre/react\"","subcomponents":["AppLayout","SidebarHeader","SidebarContent","SidebarSection","SidebarItem","SidebarFooter"],"props":{"variant":{"type":"enum","values":["default","floating"],"default":"default"}},"examples":[{"description":"App layout with sidebar","code":"<AppLayout>\n  <Sidebar>\n    <SidebarHeader>Logo</SidebarHeader>\n    <SidebarContent>\n      <SidebarSection heading=\"Main\">\n        <SidebarItem href=\"/\" active>Dashboard</SidebarItem>\n        <SidebarItem href=\"/settings\">Settings</SidebarItem>\n      </SidebarSection>\n    </SidebarContent>\n    <SidebarFooter><Avatar fallback=\"JD\" size=\"sm\" /></SidebarFooter>\n  </Sidebar>\n  <main>Page content</main>\n</AppLayout>"}]},"Skeleton":{"description":"Loading placeholder that mimics the shape of content while data loads.","import":"import { Skeleton } from \"@usevyre/react\"","props":{"variant":{"type":"enum","values":["rect","circle","text"],"default":"rect","description":"Shape of the skeleton. 'circle' for avatars, 'text' for text lines, 'rect' for blocks"},"width":{"type":"string | number","description":"Width (e.g. '200px' or '100%')"},"height":{"type":"string | number","description":"Height (e.g. '20px' or 40)"}},"examples":[{"description":"Avatar skeleton","code":"<Skeleton variant=\"circle\" width={40} height={40} />"},{"description":"Text line skeletons","code":"<Skeleton variant=\"text\" width=\"100%\" />\n<Skeleton variant=\"text\" width=\"60%\" />"}]},"Slider":{"description":"Range input for selecting a numeric value within a range.","import":"import { Slider } from \"@usevyre/react\"","props":{"value":{"type":"number","description":"Controlled value"},"onChange":{"type":"function","description":"Called with new numeric value"},"min":{"type":"number","default":0},"max":{"type":"number","default":100},"step":{"type":"number","default":1},"size":{"type":"enum","values":["sm","md"],"default":"md"},"disabled":{"type":"boolean","default":false}},"examples":[{"description":"Volume slider","code":"<Slider value={volume} onChange={setVolume} min={0} max={100} step={5} />"}]},"Switch":{"description":"Toggle switch for boolean on/off settings.","import":"import { Switch } from \"@usevyre/react\"","props":{"checked":{"type":"boolean","description":"Controlled checked state"},"onChange":{"type":"function","description":"Called with new boolean value"},"size":{"type":"enum","values":["sm","md"],"default":"md"},"disabled":{"type":"boolean","default":false}},"examples":[{"description":"Notifications toggle","code":"<label style={{ display: 'flex', alignItems: 'center', gap: 'var(--vyre-spacing-2)' }}>\n  <Switch checked={notifications} onChange={setNotifications} />\n  Enable notifications\n</label>"}]},"Table":{"description":"Data table with optional sorting. Compose with TableHeader, TableRow, TableCell.","import":"import { Table, TableHead, TableBody, TableRow, TableHeader, TableCell } from \"@usevyre/react\"","subcomponents":["TableHead","TableBody","TableRow","TableHeader","TableCell"],"props":{},"examples":[{"description":"Basic data table","code":"<Table>\n  <TableHead>\n    <TableRow>\n      <TableHeader>Name</TableHeader>\n      <TableHeader>Status</TableHeader>\n    </TableRow>\n  </TableHead>\n  <TableBody>\n    <TableRow>\n      <TableCell>Alice</TableCell>\n      <TableCell><Badge variant=\"success\">Active</Badge></TableCell>\n    </TableRow>\n  </TableBody>\n</Table>"}]},"Tabs":{"description":"Tabbed navigation for switching between content panels.","import":"import { Tabs, TabList, Tab, TabPanels, TabPanel } from \"@usevyre/react\"","subcomponents":["TabList","Tab","TabPanels","TabPanel"],"props":{"defaultIndex":{"type":"number","default":0,"description":"Index of the initially active tab (uncontrolled)"},"index":{"type":"number","description":"Controlled active tab index"},"onChange":{"type":"function","description":"Called with new index when tab changes"}},"examples":[{"description":"Basic tabs","code":"<Tabs defaultIndex={0}>\n  <TabList>\n    <Tab>Overview</Tab>\n    <Tab>Settings</Tab>\n  </TabList>\n  <TabPanels>\n    <TabPanel>Overview content</TabPanel>\n    <TabPanel>Settings content</TabPanel>\n  </TabPanels>\n</Tabs>"}]},"Toast":{"description":"Transient notification. Use the useToast hook to trigger toasts imperatively. React: wrap app in <ToastProvider>. Vue: place <ToastViewport /> once in app root.","import":"import { useToast, ToastProvider } from \"@usevyre/react\" // Vue: import { useToast, ToastViewport } from \"@usevyre/vue\"","props":{"variant":{"type":"enum","values":["default","success","warning","danger"],"default":"default","description":"Color and icon of the toast"},"title":{"type":"string","description":"Bold heading text"},"description":{"type":"string","description":"Supporting detail text"},"duration":{"type":"number","default":4000,"description":"Auto-dismiss time in milliseconds"}},"antiPatterns":[{"pattern":"Rendering <Toast> directly in JSX","reason":"Toast is triggered via the useToast hook, not rendered directly","fix":"Use: const { toast } = useToast(); then toast({ title, variant })"},{"pattern":"variant=\"error\"","reason":"No 'error' variant","fix":"Use variant=\"danger\""},{"pattern":"variant=\"info\"","reason":"No 'info' variant on Toast","fix":"Use variant=\"default\""}],"examples":[{"description":"Trigger a success toast","code":"const { toast } = useToast();\n\n<Button onClick={() => toast({ title: 'Saved!', variant: 'success', duration: 3000 })}>\n  Save\n</Button>"},{"description":"Setup: wrap app with ToastProvider","code":"<ToastProvider>\n  <App />\n</ToastProvider>"}]},"Tooltip":{"description":"Short label that appears on hover/focus. For rich content use Popover instead.","import":"import { Tooltip } from \"@usevyre/react\"","props":{"content":{"type":"string | ReactNode","description":"Text or element shown in the tooltip"},"placement":{"type":"enum","values":["top","bottom","left","right"],"default":"top"},"delay":{"type":"number","default":300,"description":"Delay in ms before tooltip appears"}},"antiPatterns":[{"pattern":"Using Tooltip for rich content (forms, buttons, etc.)","reason":"Tooltip is for short text labels only","fix":"Use Popover for rich interactive content"}],"examples":[{"description":"Tooltip on an icon button","code":"<Tooltip content=\"Close dialog\" placement=\"bottom\">\n  <Button variant=\"ghost\" size=\"icon\" aria-label=\"Close\">\n    <X size={16} />\n  </Button>\n</Tooltip>"}]},"Typography":{"description":"Text rendering components with semantic scale. Includes Text, Heading, Lead, Code, Blockquote.","import":"import { Text, Heading, Lead, Code, Blockquote } from \"@usevyre/react\"","subcomponents":["Text","Heading","Lead","Code","Blockquote"],"textProps":{"size":{"type":"enum","values":["xs","sm","md","lg","xl"],"default":"md"}},"headingProps":{"size":{"type":"enum","values":["xs","sm","md","lg","xl","2xl","3xl"],"default":"lg"},"as":{"type":"enum","values":["h1","h2","h3","h4","h5","h6"],"default":"h2"}},"antiPatterns":[{"pattern":"Using raw <h1>, <p> tags instead of Typography components","reason":"Typography components apply the correct token-based styles","fix":"Use <Heading>, <Text>, <Lead> from @usevyre/react"}],"examples":[{"description":"Page heading and body text","code":"<Heading size=\"2xl\" as=\"h1\">Dashboard</Heading>\n<Lead>Welcome back. Here's what's happening today.</Lead>\n<Text size=\"sm\" style={{ color: 'var(--vyre-color-semantic-text-muted)' }}>Last updated 5 minutes ago.</Text>"}]},"ButtonGroup":{"description":"Groups multiple Button components into one visual unit (toolbar, segmented control). Pure layout — no internal state.","import":"import { ButtonGroup, Button } from \"@usevyre/react\"","props":{"orientation":{"type":"enum","values":["horizontal","vertical"],"default":"horizontal","description":"Layout direction of grouped buttons"},"attached":{"type":"boolean","default":false,"description":"Remove gap so buttons share collapsed borders (segmented control look)"},"size":{"type":"enum","values":["sm","md","lg","icon"],"description":"Size forwarded to all child buttons"}},"antiPatterns":[{"pattern":"ButtonGroup variant=\"...\"","reason":"ButtonGroup has no variant prop — variant goes on each child Button","fix":"Set variant on each <Button> inside the group"},{"pattern":"ButtonGroup without Button children","reason":"ButtonGroup is a layout wrapper for Button elements","fix":"Place <Button> elements as direct children"}],"examples":[{"description":"Segmented control","code":"<ButtonGroup attached>\n  <Button variant=\"secondary\">Day</Button>\n  <Button variant=\"secondary\">Week</Button>\n  <Button variant=\"secondary\">Month</Button>\n</ButtonGroup>"},{"description":"Vertical group","code":"<ButtonGroup orientation=\"vertical\" attached>\n  <Button variant=\"secondary\">Top</Button>\n  <Button variant=\"secondary\">Bottom</Button>\n</ButtonGroup>"}]},"TagsInput":{"description":"Multi-tag input. Type and press Enter or comma to add a tag, click x to remove, Backspace on empty input removes the last tag. Controlled.","import":"import { TagsInput } from \"@usevyre/react\"","props":{"value":{"type":"string[]","description":"Controlled list of tags (required)"},"onChange":{"type":"(tags: string[]) => void","description":"Called with the new tag array on every change. React only — Vue uses v-model"},"placeholder":{"type":"string","description":"Input placeholder, hidden when max is reached"},"disabled":{"type":"boolean","default":false,"description":"Disables all interaction"},"max":{"type":"number","description":"Maximum number of tags; input is disabled when reached"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Size scale"}},"antiPatterns":[{"pattern":"TagsInput value={string}","reason":"value must be a string array, not a string","fix":"Pass an array: value={['react','vue']}"},{"pattern":"TagsInput without onChange","reason":"TagsInput is controlled — it needs onChange to update","fix":"Provide value and onChange (React) or v-model (Vue)"}],"examples":[{"description":"Basic tags input","code":"const [tags, setTags] = useState<string[]>([]);\n<TagsInput value={tags} onChange={setTags} placeholder=\"Add a tag…\" />"},{"description":"Limited to 5 tags","code":"<TagsInput value={tags} onChange={setTags} max={5} />"}]},"Combobox":{"description":"Searchable single-select dropdown with typeahead filtering and keyboard navigation. Use when the list is long enough to need search. Differs from Select (no search) and Command (palette).","import":"import { Combobox } from \"@usevyre/react\"","props":{"options":{"type":"{ value: string; label: string; disabled?: boolean }[]","description":"Selectable options (required)"},"value":{"type":"string | null","description":"Controlled selected value; null clears selection (required)"},"onChange":{"type":"(value: string | null) => void","description":"Called when selection changes. React only — Vue uses v-model"},"placeholder":{"type":"string","default":"\"Search…\"","description":"Input placeholder when nothing is selected"},"disabled":{"type":"boolean","default":false,"description":"Disables the combobox"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Height scale"},"emptyText":{"type":"string","default":"\"No results\"","description":"Text shown when search matches no options"}},"antiPatterns":[{"pattern":"Combobox value=\"\"","reason":"Empty selection must be null, not empty string","fix":"Use value={null} for no selection"},{"pattern":"Combobox options={string[]}","reason":"options must be objects with value and label","fix":"Use [{ value: 'ts', label: 'TypeScript' }]"},{"pattern":"Using Combobox for command palette","reason":"Combobox is single-value select, not an action palette","fix":"Use Command for command palettes"}],"examples":[{"description":"Searchable language picker","code":"const [lang, setLang] = useState<string | null>(null);\n<Combobox\n  options={[{ value: \"ts\", label: \"TypeScript\" }, { value: \"go\", label: \"Go\" }]}\n  value={lang}\n  onChange={setLang}\n  placeholder=\"Search language…\"\n/>"}]},"DataGrid":{"description":"Table with built-in column sorting, loading skeletons, and empty state. Filtering and pagination are out of scope — compose with the Pagination component.","import":"import { DataGrid } from \"@usevyre/react\"","props":{"columns":{"type":"{ key: string; label: string; sortable?: boolean; width?: string }[]","description":"Column definitions (required)"},"rows":{"type":"Record<string, unknown>[]","description":"Row data; each object keyed by column key (required)"},"sortKey":{"type":"string","description":"Controlled active sort column key"},"sortDir":{"type":"enum","values":["asc","desc"],"description":"Controlled sort direction"},"onSort":{"type":"(key: string, dir: 'asc' | 'desc') => void","description":"Called when a sortable header is clicked. React only — Vue emits sort + v-model:sortKey/sortDir"},"loading":{"type":"boolean","default":false,"description":"Show skeleton placeholder rows"},"emptyText":{"type":"string","default":"\"No data\"","description":"Message shown when rows is empty"},"stickyHeader":{"type":"boolean","default":false,"description":"Keep the header visible while scrolling"}},"antiPatterns":[{"pattern":"DataGrid expecting built-in pagination","reason":"DataGrid does not paginate — it only sorts","fix":"Slice rows yourself and use the Pagination component"},{"pattern":"DataGrid expecting built-in filtering","reason":"DataGrid does not filter rows","fix":"Filter the rows array before passing it in"},{"pattern":"sortable without onSort","reason":"Sorting is controlled — the grid does not sort data itself","fix":"Handle onSort and sort the rows array in your state"}],"examples":[{"description":"Sortable grid","code":"const cols = [{ key: \"name\", label: \"Name\", sortable: true }];\n<DataGrid\n  columns={cols}\n  rows={people}\n  sortKey={sortKey}\n  sortDir={sortDir}\n  onSort={(k, d) => { setSortKey(k); setSortDir(d); }}\n/>"},{"description":"Loading state","code":"<DataGrid columns={cols} rows={[]} loading />"}]},"Tag":{"description":"Standalone display tag/chip for categories, labels, or filter chips. NOT an input — for tag input use TagsInput. Group multiple with TagGroup.","import":"import { Tag } from \"@usevyre/react\"","props":{"variant":{"type":"enum","values":["default","accent","danger"],"default":"default","description":"Visual style. default=neutral, accent=brand, danger=destructive/error"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Size scale"},"onRemove":{"type":"() => void","description":"React only. When provided, renders a × remove button. Vue: use `removable` prop + @remove event"},"onClick":{"type":"() => void","description":"React only. When provided, makes the whole tag interactive (keyboard accessible). Vue: use `clickable` prop + @click event"},"disabled":{"type":"boolean","default":false,"description":"Disables interaction (only relevant with onClick/onRemove)"}},"antiPatterns":[{"pattern":"Tag variant=\"success\"","reason":"Tag only has default, accent, danger variants (unlike Badge which has more)","fix":"Use Badge for success/warning/teal status colors; Tag is for categories/filters"},{"pattern":"Using Tag for tag input","reason":"Tag is display-only, it does not accept typed input","fix":"Use TagsInput for adding/removing tags via keyboard"},{"pattern":"Tag size=\"xl\"","reason":"Maximum size is 'lg'","fix":"Use size=\"lg\""}],"examples":[{"description":"Category tags in a group","code":"<TagGroup>\n  <Tag>Design</Tag>\n  <Tag variant=\"accent\">Featured</Tag>\n  <Tag>Engineering</Tag>\n</TagGroup>"},{"description":"Removable filter chip (React)","code":"<Tag onRemove={() => removeFilter(\"react\")}>react</Tag>"},{"description":"Clickable toggle tag (React)","code":"<Tag onClick={() => toggleFilter(\"vue\")}>vue</Tag>"}]},"TagGroup":{"description":"Read-only container that lays out multiple Tag elements with automatic wrapping and consistent spacing. For tag input use TagsInput.","import":"import { TagGroup, Tag } from \"@usevyre/react\"","props":{"gap":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Spacing between tags"},"wrap":{"type":"boolean","default":true,"description":"Wrap tags onto multiple lines when they overflow; set false for single-line scroll"}},"antiPatterns":[{"pattern":"TagGroup without Tag children","reason":"TagGroup is a layout wrapper for Tag elements","fix":"Place <Tag> elements as direct children"},{"pattern":"Using TagGroup for tag input","reason":"TagGroup is display-only","fix":"Use TagsInput for an editable tag field"}],"examples":[{"description":"Tag group with mixed variants","code":"<TagGroup gap=\"sm\">\n  <Tag>React</Tag>\n  <Tag>Vue</Tag>\n  <Tag variant=\"accent\">TypeScript</Tag>\n</TagGroup>"}]},"Item":{"description":"Layout primitive for list rows, settings rows, and notification rows. Denser than Card — use Item (not Card) for repeated list rows.","import":"import { Item, ItemMedia, ItemContent, ItemTitle, ItemDescription, ItemActions, ItemGroup } from \"@usevyre/react\"","subcomponents":["ItemGroup","ItemMedia","ItemContent","ItemTitle","ItemDescription","ItemActions"],"props":{"variant":{"type":"enum","values":["default","outlined","muted","plain"],"default":"default","description":"Visual style of the row. plain = transparent + no border (use when composing Item inside another surface like Card or a Kanban card to avoid a double background)."},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Vertical density / text size of the row"},"clickable":{"type":"boolean","default":false,"description":"Adds pointer cursor, hover background, focus ring, and role=button"}},"antiPatterns":[{"pattern":"Card used for repeated list rows","reason":"Card is a content container; Item is the dense list-row primitive","fix":"Use <Item> (optionally inside <ItemGroup separated>) for list/settings rows"},{"pattern":"Item variant=\"primary\"","reason":"Item has no 'primary' variant","fix":"Use variant=\"default\" | \"outlined\" | \"muted\""},{"pattern":"raw text directly inside Item","reason":"Item lays out media/content/actions columns; bare text breaks alignment","fix":"Wrap text in <ItemContent><ItemTitle>…</ItemTitle></ItemContent>"}],"examples":[{"description":"Settings row with media, content and a trailing switch","code":"<Item>\n  <ItemMedia><BellIcon /></ItemMedia>\n  <ItemContent>\n    <ItemTitle>Notifications</ItemTitle>\n    <ItemDescription>Receive an email when someone mentions you.</ItemDescription>\n  </ItemContent>\n  <ItemActions>\n    <Switch defaultChecked />\n  </ItemActions>\n</Item>"},{"description":"Grouped clickable list with dividers","code":"<ItemGroup separated>\n  <Item clickable>\n    <ItemContent><ItemTitle>Profile</ItemTitle></ItemContent>\n  </Item>\n  <Item clickable>\n    <ItemContent><ItemTitle>Billing</ItemTitle></ItemContent>\n  </Item>\n</ItemGroup>"}]},"Kanban":{"description":"Drag-and-drop board: cards move between columns (or reorder within a column). CONTROLLED & data-driven like DataGrid. While dragging, a placeholder shows the exact drop position. Each card is wrapped in a Card (variant=\"outlined\"); renderCard (React) / #card slot (Vue) can render ANY content incl. complex components (Avatar/Badge/Progress). Columns and cards accept an optional semantic color tint. Native HTML5 DnD, zero deps.","import":"import { Kanban } from \"@usevyre/react\"","props":{"value":{"type":"KanbanColumn[]","description":"Controlled board data. KanbanColumn = { id, title, cards: KanbanCard[], color? }; KanbanCard = { id, title, description?, color? }. Extra app fields may ride along on cards and be read in renderCard. color = \"default\"|\"accent\"|\"teal\"|\"success\"|\"warning\"|\"danger\" (token-based tint). Card ids must be unique across the whole board."},"onChange":{"type":"function","description":"(next: KanbanColumn[]) => void — called with the next columns array after a drag move. Required; set it back into your state."},"renderCard":{"type":"function","description":"(card, column) => ReactNode — custom card body, rendered inside the wrapping <Card>. Vue: #card scoped slot. Can return any components (Avatar, Badge, Progress, etc.); attach extra fields to the card object and read them here."},"onCardClick":{"type":"function","description":"(card, column) => void — fired on click/Enter/Space (not after a drag). Vue: @card-click."}},"antiPatterns":[{"pattern":"Kanban without onChange (or ignoring it)","reason":"Kanban holds no internal data state; dropped cards won't move unless you apply onChange","fix":"Store columns in state and setColumns in onChange (v-model in Vue)"},{"pattern":"Duplicate card ids across columns","reason":"Card moves are resolved by id; duplicates corrupt the move","fix":"Use globally-unique card ids across the entire board"},{"pattern":"Mutating value in place then calling onChange","reason":"React/Vue need a new array reference to re-render reliably","fix":"Pass the new array Kanban gives you straight to setState / v-model"},{"pattern":"color=\"blue\" (or any non-semantic value)","reason":"color is a fixed semantic set, not an arbitrary CSS color","fix":"Use one of: \"default\" | \"accent\" | \"teal\" | \"success\" | \"warning\" | \"danger\""}],"examples":[{"description":"Controlled board","code":"const [columns, setColumns] = useState([\n  { id: \"todo\",  title: \"To Do\",       cards: [{ id: \"1\", title: \"Spec API\" }] },\n  { id: \"doing\", title: \"In Progress\", cards: [] },\n  { id: \"done\",  title: \"Done\",        cards: [{ id: \"2\", title: \"Kickoff\" }] },\n]);\n<Kanban value={columns} onChange={setColumns} />"},{"description":"Custom card body + click handler","code":"<Kanban\n  value={columns}\n  onChange={setColumns}\n  onCardClick={(card) => openDetail(card.id)}\n  renderCard={(card) => (\n    <><strong>{card.title}</strong><Badge>{card.id}</Badge></>\n  )}\n/>"},{"description":"Tinted columns/cards + complex card content","code":"const [cols, setCols] = useState([\n  { id: \"doing\", title: \"In Progress\", color: \"teal\", cards: [\n    { id: \"t1\", title: \"OAuth\", assignee: \"AK\", progress: 60, color: \"warning\" },\n  ]},\n]);\n<Kanban\n  value={cols}\n  onChange={setCols}\n  renderCard={(card) => (\n    <><strong>{card.title}</strong><Progress value={card.progress} /></>\n  )}\n/>"}]},"Conversation":{"description":"Chat / inbox message thread. CONTROLLED & data-driven like Kanban — you own `value` (messages array) and append in your own send handler; Conversation holds no message state. Consecutive messages from the same author are grouped (avatar + name shown once), day separators are inserted on date change, and outgoing messages (authorId === currentUserId) align right.","import":"import { Conversation } from \"@usevyre/react\"","props":{"value":{"type":"ConversationMessage[]","description":"Ordered messages. ConversationMessage = { id, authorId, text?, authorName?, authorAvatar?, timestamp?: Date|string|number, status?: \"sending\"|\"sent\"|\"delivered\"|\"read\", attachments?: ConversationAttachment[] }. ConversationAttachment = { kind: \"image\"|\"audio\"|\"video\"|\"file\", url, name?, size? } — rendered inside the bubble. Required & controlled."},"currentUserId":{"type":"string","description":"Whose messages are outgoing (aligned right). Required — match against message.authorId."},"composer":{"type":"boolean","default":false,"description":"Show the built-in input + Send button. Pair with onSend."},"onSend":{"type":"function","description":"(text: string, files: File[]) => void — called when the built-in composer submits. files holds anything staged via the attach button (empty array unless allowAttachments). You own the upload + turning staged files into message attachments. Vue: @send."},"placeholder":{"type":"string","default":"Write a message…","description":"Composer input placeholder."},"typing":{"type":"boolean | string","default":false,"description":"Show an incoming typing indicator. Pass a string to label it."},"allowAttachments":{"type":"boolean","default":false,"description":"Show a 📎 attach button + staged-file chips in the built-in composer. Files come back via onSend's second arg."},"accept":{"type":"string","description":"Forwarded to the file input's accept attribute, e.g. \"image/*\"."},"renderMessage":{"type":"function","description":"(message, meta) => ReactNode — custom bubble body. meta = { outgoing, isGroupStart, isGroupEnd }. Vue: #message scoped slot."},"renderComposer":{"type":"function","description":"(api) => ReactNode — replace the composer entirely. api = { value, setValue, files, setFiles, send }. Vue: #composer scoped slot."}},"antiPatterns":[{"pattern":"Conversation without currentUserId","reason":"Alignment (incoming vs outgoing) is decided by authorId === currentUserId","fix":"Always pass currentUserId matching one of the message authorId values"},{"pattern":"Expecting Conversation to store/append messages","reason":"Conversation is controlled & stateless for data, like Kanban/DataGrid","fix":"Append to your own state in onSend (or @send) and pass it back via value"},{"pattern":"composer without onSend (React) / @send (Vue)","reason":"The built-in composer emits text; nothing happens unless you handle it","fix":"Provide onSend / @send to append the message to value"},{"pattern":"Treating onSend as (text) only when using allowAttachments","reason":"With allowAttachments, staged files arrive as the 2nd arg; ignoring it drops attachments","fix":"Handle onSend(text, files) — map files to message attachments and append"}],"examples":[{"description":"Controlled thread with built-in composer","code":"const [messages, setMessages] = useState([\n  { id: \"1\", authorId: \"sam\", authorName: \"Sam\", text: \"Hey!\" },\n  { id: \"2\", authorId: \"me\", text: \"Hi \\ud83d\\udc4b\", status: \"read\" },\n]);\n<Conversation\n  value={messages}\n  currentUserId=\"me\"\n  composer\n  onSend={(t) => setMessages((m) => [...m, { id: crypto.randomUUID(), authorId: \"me\", text: t }])}\n/>"},{"description":"Typing indicator + custom bubble","code":"<Conversation\n  value={messages}\n  currentUserId=\"me\"\n  typing=\"Sam is typing\"\n  renderMessage={(m) => <strong>{m.text}</strong>}\n/>"},{"description":"Message with image + file attachments","code":"const messages = [\n  { id: \"1\", authorId: \"sam\", authorName: \"Sam\", text: \"Moodboard \\ud83d\\udc47\",\n    attachments: [{ kind: \"image\", url: \"/board.png\", name: \"board.png\" }] },\n  { id: \"2\", authorId: \"me\", text: \"Specs:\", status: \"read\",\n    attachments: [{ kind: \"file\", url: \"/spec.pdf\", name: \"spec.pdf\", size: \"2.4 MB\" }] },\n];\n<Conversation value={messages} currentUserId=\"me\" />"}]},"DateRangePicker":{"description":"Start/end date range picker. Built on Calendar (mode=range) with a friendlier { from, to } object API, a two-month side-by-side view, and preset shortcuts. Use this for report/filter date ranges; use DatePicker for a single date.","import":"import { DateRangePicker } from \"@usevyre/react\"","props":{"value":{"type":"{ from: Date | null; to: Date | null } | null","description":"Selected range (controlled). Pass an OBJECT, not a tuple."},"onChange":{"type":"function","description":"Callback (range: { from, to }) => void when the range changes"},"placeholder":{"type":"string","default":"Pick a date range","description":"Trigger text when no range is selected"},"numberOfMonths":{"type":"enum","values":[1,2],"default":2,"description":"How many month calendars to show side-by-side"},"presets":{"type":"boolean | DateRangePreset[]","default":false,"description":"true shows built-in presets (Today, Yesterday, Last 7/30 days, This/Last month); or pass a custom array of { label, range() }"},"minDate":{"type":"Date","description":"Earliest selectable date"},"maxDate":{"type":"Date","description":"Latest selectable date"},"disabled":{"type":"function","description":"(date: Date) => boolean — disable specific dates"},"weekStartsOn":{"type":"enum","values":[0,1],"default":1,"description":"0 = Sunday, 1 = Monday"}},"antiPatterns":[{"pattern":"value={[from, to]}","reason":"DateRangePicker uses a { from, to } object, not a [Date, Date] tuple like Calendar mode=range","fix":"Use value={{ from, to }} and read range.from / range.to"},{"pattern":"DateRangePicker for a single date","reason":"DateRangePicker always selects a start AND end","fix":"Use <DatePicker /> for a single date"},{"pattern":"presets=\"true\" (string)","reason":"presets is a boolean or an array, not a string","fix":"Use the bare prop: presets  (or presets={true})"}],"examples":[{"description":"Range picker with built-in presets","code":"const [range, setRange] = useState({ from: null, to: null });\n<DateRangePicker value={range} onChange={setRange} presets />"},{"description":"Single month, no presets","code":"<DateRangePicker value={range} onChange={setRange} numberOfMonths={1} />"}]}}};
